    func runEnded(error: (any Error)?) {
        runningMedia = nil
        cloud = nil
        token = nil
        lastError = error?.localizedDescription
        if let document = document {
            input = FillerDetector.read(from: document, clips: nil)
        }
        rebuildRows()
        refresh()
